<?php require '../common.php';startpage('Hotel Booking History');nav('<a href="index.php">Rooms</a>');$name=$_GET['guest']??'';?><form><input name="guest" placeholder="Guest name" value="<?=e($name)?>" required><button>Search</button></form><?php if($name):$s=$conn->prepare('SELECT b.*,r.room_type FROM hotel_bookings b JOIN rooms r ON r.id=b.room_id WHERE b.guest=?');$s->bind_param('s',$name);$s->execute();$rs=$s->get_result();?><table><tr><th>ID</th><th>Room</th><th>Dates</th><th>Guests</th><th>Status</th></tr><?php while($b=$rs->fetch_assoc()):?><tr><td><?=$b['id']?></td><td><?=e($b['room_type'])?></td><td><?=$b['checkin']?> to <?=$b['checkout']?></td><td><?=$b['guests']?></td><td><?=e($b['status'])?></td></tr><?php endwhile;?></table><?php endif;endpage();?>